   109→	public CharVector trim() {
   110→		while (length > 0 && array[offset] == ' ') {
   111→			offset++;
   112→			length--;
   113→		}
   114→		while (length > 0 && array[offset + length - 1] == ' ') {
   115→			length--;
   116→		}
   117→		hash = 0;
   118→		return this;
   119→	}
