   387→    public static void mergeSubQueue(RuleEntry entry, List<RuleEntry> subQueue, AnalyzerOption option, SetDictionary unitDictionary) {
   388→        if (entry.type == MODEL_NAME) {
   389→            // 바이트 비교가 많으므로 버퍼기준으로 처리하도록 한다.
   390→            boolean processed = false;
   391→            if (subQueue.size() == 3) {
   392→                // 모델명이 3블럭이며, 가운데 기호가 있는 경우, 붙여서만 출력함.
   393→                // 단위명 + 1글자 등의 조합으로 나올수 있으므로 일단 합쳐서 체크하도록 한다.
   394→                int contCnt = 0;
   395→                RuleEntry initEntry = subQueue.get(0).clone();
   396→                RuleEntry prevEntry = initEntry;
   397→                for (int cinx = 1; cinx < subQueue.size(); cinx++, contCnt++) {
   398→                    RuleEntry currentEntry = subQueue.get(cinx);
   399→                    if (prevEntry.startOffset + prevEntry.length != currentEntry.startOffset) {
   400→                        break;
   401→                    }
   402→                    initEntry.length += currentEntry.length;
   403→                    prevEntry = currentEntry;
   404→                }
   405→                // 합칠수 있는 블럭인 경우.
   406→                if (contCnt > 0 && contCnt == subQueue.size() - 1) {
   407→                    if (initEntry.length == 2) {
   408→                        String charType = getType(initEntry.buf[initEntry.start]);
   409→                        String nextCharType = getType(initEntry.buf[initEntry.start + 1]);
   410→                        if ((charType == ALPHA || charType == NUMBER) &&
   411→                                // 모델명이 2블럭이며, 영숫자 + 특수기호 인 경우
   412→                                (nextCharType == SYMBOL)) {
   413→                            entry.length -= 1;
   414→                            entry.endOffset -= 1;
   415→                            entry.type = charType;
   416→                            subQueue.clear();
   417→                            processed = true;
   418→                        } else if ((charType == SYMBOL) &&
   419→                                // 모델명이 2블럭이며, 영숫자 + 특수기호 인 경우
   420→                                (nextCharType == ALPHA || nextCharType == NUMBER)) {
   421→                            entry.start++;
   422→                            entry.startOffset++;
   423→                            entry.length--;
   424→                            entry.type = nextCharType;
   425→                            subQueue.clear();
