   789→                    currentEntry.length += nextEntry.length;
   790→                    currentEntry.endOffset = currentEntry.startOffset + currentEntry.length + nextEntry.length;
   791→                    currentEntry.type = MODEL_NAME;
   792→                }
   793→            }
   794→
   795→            if (!option.useForQuery()) {
   796→                // 추가 텀 추출
   797→                exportByTriGram(subQueue, tmpList);
   798→                // 단위명 추가 텀 추출
   799→                exportUnitGram(subQueue, tmpList, unitDictionary);
   800→            }
   801→
   802→            if (tmpList.size() > 0) {
   803→                subQueue.addAll(tmpList);
   804→            }
   805→            ////////////////////////////////////////////////////////////////////////////////
   806→            Collections.sort(subQueue);
   807→        }
   808→    }
