   872→    private static void exportUnitGram(List<RuleEntry> subQueue, List<RuleEntry> tmpList, SetDictionary unitDictionary) {
   873→        Iterator<RuleEntry> iter = subQueue.iterator();
   874→        RuleEntry currentEntry = null;
   875→
   876→        while (iter.hasNext()) {
   877→            // init
   878→            if (currentEntry == null) {
   879→                currentEntry = iter.next();
   880→            }
   881→
   882→            if (iter.hasNext()) {
   883→                RuleEntry nextEntry = iter.next();
   884→
   885→                // 이미 결합됨
   886→                if (currentEntry.length == 1 && nextEntry.length == 1) {
   887→                    currentEntry = nextEntry;
   888→                    continue;
   889→                }
   890→
   891→                CharVector unitCandidate = new CharVector();
   892→                unitCandidate.init(nextEntry.buf, nextEntry.start, nextEntry.length);
   893→
   894→                if (unitDictionary != null && unitDictionary.set().contains(unitCandidate)) {
   895→                    nextEntry.type = UNIT;
   896→                }
   897→
   898→                if (currentEntry.type == NUMBER && (nextEntry.type == UNIT || nextEntry.type == UNIT_ALPHA)) {
   899→                    // 현재와 다음 엔트리를 비교 및 결합한다
   900→                    combineNextUnitEntry(tmpList, currentEntry, nextEntry, UNIT);
   901→                }
   902→                currentEntry = nextEntry;
   903→            }
   904→        }
   905→    }
