   914→    private static void combineNextNextEntry(List<RuleEntry> tmpList, RuleEntry currentEntry, RuleEntry nextEntry, RuleEntry nextNextEntry, String type) {
   915→        if (nextNextEntry != null && nextEntry.length == 1 && nextNextEntry.length == 1 && ((nextEntry.type == ALPHA || nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start])) && nextNextEntry.type == NUMBER || nextEntry.type == NUMBER && (nextNextEntry.type == ALPHA || nextNextEntry.type == UNIT && Character.isAlphabetic(nextNextEntry.buf[nextNextEntry.start])))) {
   916→            tmpList.add(mergeNewEntry(nextEntry, nextNextEntry, type));
   917→            tmpList.add(mergeNewEntry(currentEntry, nextEntry, nextNextEntry, type));
   918→        }
   919→    }
