   921→    private static void combineNextEntry(List<RuleEntry> tmpList, RuleEntry currentEntry, RuleEntry nextEntry, String type) {
   922→        if (nextEntry != null && nextEntry.length == 1 && ((nextEntry.type == ALPHA || currentEntry.type == UNIT && Character.isAlphabetic(currentEntry.buf[currentEntry.start])) || nextEntry.type == NUMBER)) {
   923→            if ((currentEntry.type == NUMBER && (nextEntry.type == ALPHA || nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start]))) || ((currentEntry.type == ALPHA || (currentEntry.type == UNIT && Character.isAlphabetic(currentEntry.buf[currentEntry.start]))) && nextEntry.type == NUMBER)) {
