    10→import static com.danawa.search.analysis.product.ProductNameTokenizer.*;
    11→import static com.danawa.search.analysis.product.ProductNameTokenizer.NUMBER;
    12→
    13→public class RuleThree extends Rule {
    14→
    15→    public RuleThree(Entry entry, boolean fullExtract, AnalyzerOption option,
    16→                     SetDictionary unitDictionary, SynonymDictionary unitSynonymDictionary) {
    17→        super(entry, fullExtract, option);
    18→        this.unitDictionary = unitDictionary;
    19→        this.unitSynonymDictionary = unitSynonymDictionary;
    20→    }
    21→
    22→    @Override
    23→    public void apply(List<RuleEntry> queue) {
    24→        RuleEntry nextNextEntry = null;
    25→
    26→        // 3차 가공, 단위명을 색출한다.
    27→        for (int qinx = 0; qinx < queue.size(); qinx++) {
    28→            RuleEntry currentEntry = queue.get(qinx);
    29→            if (isFullStringEntry(currentEntry)) {
    30→                continue;
    31→            }
    32→
    33→            if (existNextIndex(queue, qinx)) {
    34→                RuleEntry nextEntry = queue.get(qinx + 1);
    35→
    36→                // 숫자가 포함된 엔트리일 경우
    37→                if (isConnectedNumberEntry(currentEntry, nextEntry)) {
    38→                    nextNextEntry = getUnit(queue, nextNextEntry, qinx, currentEntry, nextEntry);
    39→                }
    40→            }
    41→        }
    42→
    43→        logger.trace("3rd process complete / queue:{}", queue);
    44→    }
    45→
    46→    private RuleEntry getUnit(List<RuleEntry> queue, RuleEntry nextNextEntry, int qinx, RuleEntry currentEntry, RuleEntry nextEntry) {
    47→        CharVector unitCandidate = new CharVector();
    48→        unitCandidate.init(nextEntry.buf, nextEntry.start, nextEntry.length);
    49→
    50→        int findInx = 5;
    51→        boolean foundUnit = false;
    52→        for (; findInx > 0; findInx--) {
    53→            if (qinx + findInx < queue.size()) {
    54→                RuleEntry prevEntry = queue.get(qinx + findInx);
    55→
    56→                // 길이가 0 이거나 한글 엔트리 제외
    57→                if (prevEntry.length == 0 || (findInx > 1 && isHangulEntry(prevEntry))) { continue; }
    58→
    59→                // 단위명 길이 추출
    60→                int unitLength = getUnitLength(nextEntry, prevEntry);
    61→
    62→                // 단위명 사전 제한 길이 이하
    63→                if (unitLength <= MAX_UNIT_LENGTH) {
    64→                    if (nextEntry.buf.length >= nextEntry.start + unitLength) {
    65→                        unitCandidate.init(nextEntry.buf, nextEntry.start, unitLength);
    66→
    67→                        // 단위명 사전에서 검색
    68→                        if (findUnitDictionary(unitCandidate, getUniType(unitCandidate))) {
    69→                            foundUnit = true;
    70→                            break;
    71→                        }
    72→                    }
    73→                }
    74→            }
    75→        }
    76→
    77→        // 단위명이 발견되었을 경우
    78→        if (foundUnit) {
    79→            nextNextEntry = getRuleEntry(queue, nextNextEntry, qinx, currentEntry, nextEntry, unitCandidate, findInx);
    80→        }
    81→        return nextNextEntry;
    82→    }
    83→
    84→    private int getUnitLength(RuleEntry nextEntry, RuleEntry prevEntry) {
    85→        int unitLength;
    86→        if (isSameBuffer(nextEntry, prevEntry)) {
    87→            unitLength = prevEntry.start + prevEntry.length - nextEntry.start;
    88→        } else {
    89→            // PrevEntry, NextEntry 버퍼가 다르다면, 서로의 포지션은 영향을 주지 않는다.
    90→            unitLength = nextEntry.length;
    91→        }
    92→        return unitLength;
    93→    }
    94→
    95→    private boolean isSameBuffer(RuleEntry nextEntry, RuleEntry prevEntry) {
    96→        return prevEntry.buf == nextEntry.buf;
    97→    }
    98→
    99→    private boolean isConnectedNumberEntry(RuleEntry currentEntry, RuleEntry nextEntry) {
   100→        return isConnected(currentEntry, nextEntry) && (isNumberEntry(currentEntry) || isNumberTransEntry(currentEntry));
   101→    }
   102→
   103→    private RuleEntry getRuleEntry(List<RuleEntry> queue, RuleEntry nextNextEntry, int qinx, RuleEntry currentEntry, RuleEntry nextEntry, CharVector unitCandidate, int findInx) {
   104→        String typePrev;
   105→        String unitType = getUniType(unitCandidate);
   106→        CharSequence[] units = null;
   107→        if (unitSynonymDictionary != null) {
   108→            units = unitSynonymDictionary.get(unitCandidate);
   109→        }
   110→        char tempch1 = 0x0;
   111→        if (currentEntry.start > entry.start) {
   112→            tempch1 = currentEntry.buf[currentEntry.start - 1];
   113→        }
   114→
   115→        typePrev = setTypePrev(queue, qinx);
   116→
   117→        /* findUnit에서 텀조합이 글자 줄임 없이 정확하게 매칭된 경우 */
   118→        if (isAllMatchTerm(queue, qinx, nextEntry, unitCandidate, findInx)) {
   119→            // 숫자 이전글자가 영문이며, 단위명 자투리도 영문인 경우 모델명 우선으로 인식, 예:a1024mm
   120→            if (isAlphaWithUnit(typePrev, unitType, tempch1)) {
   121→                // 단위명의 동의어가 있다면 처리한다.
   122→                processUnitSynonym(queue, qinx, currentEntry, nextEntry, unitCandidate, findInx, unitType, units);
   123→            }
   124→        } else if (isReduceTerm(nextEntry, unitCandidate)) {
   125→            /* findUnit에 의해 글자 줄임이 발생한 경우 */
   126→            // 단위명이 영문이며, 단위명 자투리도 영문인 경우 모델명으로 인식 예:1024mmcc
   127→            // 뒷단어가 바로 붙어있어야 인정. 공백이 있다면 불가.
   128→            nextNextEntry = getXNextEntry(queue, nextNextEntry, qinx);
   129→
   130→            // 모델명 우선
   131→            currentEntry.modifiable = true;
   132→            nextEntry.modifiable = true;
   133→        }
   134→        return nextNextEntry;
   135→    }
   136→
   137→    private String setTypePrev(List<RuleEntry> queue, int qinx) {
   138→        String typePrev;
   139→        if (qinx > 0) {
   140→            typePrev = queue.get(qinx - 1).type;
   141→        } else {
   142→            typePrev = null;
   143→        }
   144→        return typePrev;
   145→    }
   146→
   147→    private RuleEntry getXNextEntry(List<RuleEntry> queue, RuleEntry nextNextEntry, int qinx) {
   148→        if (qinx + 2 < queue.size()){
   149→            nextNextEntry = queue.get(qinx + 2);
   150→        }
   151→        return nextNextEntry;
   152→    }
   153→
   154→    private void processUnitSynonym(List<RuleEntry> queue, int qinx, RuleEntry currentEntry, RuleEntry nextEntry, CharVector unitCandidate, int findInx, String unitType, CharSequence[] units) {
   155→        Entry.modifyRuleEntry(fullExtract, option, currentEntry, nextEntry, unitCandidate, units, unitType);
   156→        logger.trace("currentEntry:{} / SYN:{}", currentEntry, currentEntry.synonym);
   157→        // 1,000과 같은 NUMBER_TRANS는 지우면 안됨
   158→        boolean isNumberTransEntry = false;
   159→        for(RuleEntry entry : currentEntry.subEntry){
   160→            if (entry.type == NUMBER_TRANS) {
   161→                isNumberTransEntry = true;
   162→                break;
   163→            }
   164→        }
   165→        for (; findInx >= 1; findInx--) {
   166→            // 여기서 UNIT은 모두 한글 단위, 한글 단위는 살려야하므로 not remove
   167→            if(!isNumberTransEntry && (currentEntry.type != UNIT)){
   168→                queue.remove(qinx + findInx);
   169→            } else if(option.useForQuery()){
   170→                queue.remove(qinx + findInx);
   171→            }
   172→        }
   173→    }
   174→
   175→    private boolean isAlphaWithUnit(String typePrev, String unitType, char tempch1) {
   176→        return (unitType == ALPHA && (typePrev == UNIT || typePrev == UNIT_ALPHA)) ||
   177→                !(getType(tempch1) == ALPHA && unitType == ALPHA);
   178→    }
   179→
   180→    private boolean isReduceTerm(RuleEntry nextEntry, CharVector unitCandidate) {
   181→        return nextEntry.buf.length > nextEntry.start + unitCandidate.length();
   182→    }
   183→
   184→    private boolean isAllMatchTerm(List<RuleEntry> queue, int qinx, RuleEntry nextEntry, CharVector unitCandidate, int findInx) {
   185→        return (findInx == 1 && unitCandidate.length() == nextEntry.length) ||
   186→                (findInx > 1 && (qinx + findInx) < queue.size() && unitCandidate.length() ==
   187→                        queue.get(qinx + findInx).endOffset - nextEntry.startOffset);
   188→    }
   189→
   190→    private boolean findUnitDictionary(CharVector key, String type) {
   191→        key.ignoreCase();
   192→        if (isEquals(type, ALPHA) || isEquals(type, SYMBOL)) {
   193→            if (key.length() > MAX_UNIT_LENGTH) {
   194→                key.length(MAX_UNIT_LENGTH);
   195→            }
   196→            if (checkUnitDictionary(key)) return true;
   197→            key.length(key.length() - 1);
   198→            return false;
   199→        } else {
   200→            return isContainUnitDictionary(key);
   201→        }
   202→    }
   203→
   204→    private boolean checkUnitDictionary(CharVector key) {
   205→        for (int len = key.length(); len >= 0; len--) {
   206→            key.length(len);
   207→            if (isContainUnitDictionary(key)) return true;
   208→        }
   209→        return false;
   210→    }
   211→
   212→    private boolean isContainUnitDictionary(CharVector key) {
   213→        return unitDictionary != null && unitDictionary.set().contains(key);
   214→    }
   215→}

