    41→public abstract class DataInput extends InputStream implements Cloneable {
    42→
    43→	/**
    44→	 * Reads and returns a single byte.
    45→	 * 
    46→	 * @see IndexOutput#writeByte(byte)
    47→	 */
    48→	public abstract byte readByte() throws IOException;
