   131→		 * inlined. So the loop was unwinded! byte b = readByte(); int i = b & 0x7F; for (int shift = 7; (b & 0x80) != 0; shift +=
   132→		 * 7) { b = readByte(); i |= (b & 0x7F) << shift; } return i;
   133→		 */
   134→		byte b = readByte();
   135→		if (b >= 0) { return b; }
   136→		int i = b & 0x7F;
   137→		b = readByte();
   138→		i |= (b & 0x7F) << 7;
   139→		if (b >= 0) { return i; }
   140→		b = readByte();
   141→		i |= (b & 0x7F) << 14;
   142→		if (b >= 0) { return i; }
   143→		b = readByte();
   144→		i |= (b & 0x7F) << 21;
   145→		if (b >= 0) { return i; }
   146→		b = readByte();
